def split_row(line: str):
    """Split one CSV line into fields. Fields may be double-quoted; inside a
    quoted field a comma is literal and a doubled quote is a literal quote."""
    fields = []
    field = []
    in_quotes = False
    for i, c in enumerate(line):
        if in_quotes:
            if c == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')  # doubled quote -> literal quote
                else:
                    in_quotes = False
            else:
                field.append(c)
        elif c == '"' and not field:
            in_quotes = True
        elif c == ',':
            fields.append("".join(field))
            field = []
        else:
            field.append(c)
    fields.append("".join(field))
    return fields

def split_row(line: str):
    """Split one CSV line into fields. Fields may be double-quoted; inside a
    quoted field a comma is literal and a doubled quote is a literal quote."""
    fields = []
    field = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')  # doubled quote -> literal quote
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(c)
        elif c == '"' and not field:
            in_quotes = True
        elif c == ',':
            fields.append("".join(field))
            field = []
        else:
            field.append(c)
        i += 1
    fields.append("".join(field))
    return fields
